templates.blocksRegistryClass:
package {{packageName}};

import net.minecraft.core.Registry;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.material.Material;
import net.minecraft.world.level.block.state.BlockBehaviour;

/** Blocks of {{modName}} (generated by mcmodkit). Each block also gets a matching BlockItem. */
public final class {{mainClassSimpleName}}Blocks {

{{BLOCK_REGISTRATIONS}}

	private {{mainClassSimpleName}}Blocks() {
	}

	public static void init() {
	}

	private static Block register(String name, Block block) {
		ResourceLocation id = {{mainClassSimpleName}}.id(name);
		Block registered = Registry.register(Registry.BLOCK, id, block);
		Registry.register(Registry.ITEM, id, new BlockItem(registered, new Item.Properties()));
		return registered;
	}
}

templates.tabBlock:
FabricItemGroupBuilder.create({{mainClassSimpleName}}.id("{{namespace}}"))
	.icon(() -> new ItemStack(TAB_ENTRIES.isEmpty() ? Items.STONE : TAB_ENTRIES.get(0)))
	.appendItems(stacks -> {
		for (ItemLike entry : TAB_ENTRIES) {
			stacks.add(new ItemStack(entry));
		}
	})
	.build();
